package com.brasa.restaurant.model;import jakarta.persistence.*;import java.time.Instant;import java.util.UUID;@MappedSuperclass public abstract class BaseEntity{@Id@Column(length=36)private String id;private Instant criadoEm;private Instant atualizadoEm;@PrePersist void pre(){if(id==null)id=UUID.randomUUID().toString();criadoEm=Instant.now();atualizadoEm=criadoEm;}@PreUpdate void update(){atualizadoEm=Instant.now();}public String getId(){return id;}public void setId(String id){this.id=id;}public Instant getCriadoEm(){return criadoEm;}public Instant getAtualizadoEm(){return atualizadoEm;}}
